import{_ as i,c as h,o as t,ae as a}from"./chunks/framework.BGWP4WZ_.js";const d=JSON.parse('{"title":"Danh mục tài liệu py-xiaozhi","description":"","frontmatter":{},"headers":[],"relativePath":"vi/guide/文档目录.md","filePath":"vi/guide/文档目录.md"}'),c={name:"vi/guide/文档目录.md"};function g(e,n,l,r,o,u){return t(),h("div",null,n[0]||(n[0]=[a('<h1 id="danh-muc-tai-lieu-py-xiaozhi" tabindex="-1">Danh mục tài liệu py-xiaozhi <a class="header-anchor" href="#danh-muc-tai-lieu-py-xiaozhi" aria-label="Permalink to &quot;Danh mục tài liệu py-xiaozhi&quot;">​</a></h1><p>Thư mục này chứa toàn bộ tài liệu tính năng của dự án py-xiaozhi, được phân chia theo từng mô-đun chức năng để thuận tiện tra cứu và sử dụng.</p><p>Các công cụ MCP tích hợp hiện tập trung vào những năng lực hệ thống cốt lõi: điều khiển âm lượng hệ thống, quản lý ứng dụng, nhận diện thị giác qua camera (USB / Raspberry Pi CSI) và chụp ảnh màn hình, cùng tra cứu thời tiết. Các khả năng mở rộng như âm nhạc, radio, podcast, nhà thông minh (Home Assistant) được cài đặt theo nhu cầu dưới dạng <strong>plugin MCP mở rộng</strong>, sử dụng chung nền tảng phát media độc lập với nguồn âm của ứng dụng máy chủ (<code>MediaPlayer</code> + <code>AudioMixer</code> + <code>AudioDecoder</code>).</p><p>Dự án hiện đã kích hoạt giao thức ủy quyền v2; liên kết WSS được trả về thông qua giao diện OTA, đồng bộ hóa quy trình xác thực giữa máy chủ Xiaozhi chính thức và các backend mã nguồn mở.</p><p><strong>Khi định nghĩa vai trò cho AI, hãy thêm chỉ dẫn: ưu tiên sử dụng các công cụ mở rộng bên ngoài (MCP/IoT), không được bỏ qua việc thực thi. Điều này giúp tránh việc AI không gọi MCP hoặc IoT; tuy nhiên vẫn có khả năng kích hoạt các công cụ tích hợp có chức năng tương tự, khi đó bạn có thể nhắc thêm để AI dùng đúng công cụ.</strong></p><h2 id="tai-lieu-co-ban" tabindex="-1">Tài liệu cơ bản <a class="header-anchor" href="#tai-lieu-co-ban" aria-label="Permalink to &quot;Tài liệu cơ bản&quot;">​</a></h2><ul><li><a href="./系统依赖安装.html">Cài đặt phụ thuộc hệ thống</a> - Cài đặt phụ thuộc hệ thống và cấu hình môi trường Python trên từng nền tảng</li><li><a href="./配置说明.html">Hướng dẫn cấu hình</a> - Cấu trúc tệp cấu hình, giải thích các mục cấu hình và hướng dẫn chỉnh sửa</li><li><a href="./语音交互模式说明.html">Chế độ tương tác giọng nói</a> - Tổng quan dự án, hướng dẫn sử dụng cơ bản và các chế độ chạy</li><li><a href="./回声消除.html">Khử tiếng vọng</a> - Cấu hình AEC tích hợp và các giải pháp tăng cường cấp hệ thống</li><li><a href="./语音唤醒.html">Đánh thức bằng giọng nói</a> - Hướng dẫn cấu hình và sử dụng tính năng từ đánh thức</li><li><a href="./设备激活流程.html">Quy trình kích hoạt thiết bị</a> - Hướng dẫn quy trình kích hoạt và đăng ký thiết bị</li><li><a href="./打包教程.html">Hướng dẫn đóng gói</a> - Hướng dẫn chi tiết đóng gói ứng dụng Xiaozhi bằng UnifyPy</li></ul><h2 id="tai-lieu-phat-trien" tabindex="-1">Tài liệu phát triển <a class="header-anchor" href="#tai-lieu-phat-trien" aria-label="Permalink to &quot;Tài liệu phát triển&quot;">​</a></h2><ul><li><a href="./开发指南.html">Hướng dẫn phát triển</a> - Hướng dẫn phát triển mở rộng, bao gồm phát triển plugin, công cụ MCP, giao diện UI, v.v.</li><li><a href="/py-xiaozhi/vi/mcp/">Phát triển công cụ MCP tích hợp</a> - Quy ước <code>register.py</code> và <code>register_*_tools</code></li><li><a href="/py-xiaozhi/vi/mcp/plugins.html">Plugin MCP mở rộng</a> - Gói plugin đặt trong thư mục người dùng, đi kèm phụ thuộc riêng, cài đặt là dùng ngay</li></ul><h2 id="tai-lieu-khac" tabindex="-1">Tài liệu khác <a class="header-anchor" href="#tai-lieu-khac" aria-label="Permalink to &quot;Tài liệu khác&quot;">​</a></h2><ul><li><a href="./异常汇总.html">Tổng hợp lỗi thường gặp</a> - Các sự cố thường gặp và cách khắc phục</li></ul><h2 id="tham-gia-đong-gop" tabindex="-1">Tham gia đóng góp <a class="header-anchor" href="#tham-gia-đong-gop" aria-label="Permalink to &quot;Tham gia đóng góp&quot;">​</a></h2><p>Nếu bạn muốn tham gia phát triển dự án hoặc gửi phản hồi, vui lòng tham khảo các tài nguyên sau:</p><ul><li><a href="/py-xiaozhi/vi/contributing.html">Hướng dẫn đóng góp</a> - Hướng dẫn đóng góp bản tiếng Việt, giúp nhanh chóng nắm quy trình gửi đóng góp và tiêu chuẩn đánh giá</li><li><a href="/py-xiaozhi/contributing.html">Contributing</a> - Hướng dẫn đóng góp bản tiếng Anh, bao gồm quy trình phát triển, yêu cầu PR và quy trình maintainer</li><li><a href="/py-xiaozhi/vi/about/team.html">Thành viên nhóm</a> - Cảm ơn các thành viên đã đóng góp cho dự án</li><li><a href="/py-xiaozhi/vi/sponsors/">Tài trợ &amp; Ủng hộ</a> - Cách tài trợ cho sự phát triển của dự án</li></ul><h2 id="he-sinh-thai-lien-quan" tabindex="-1">Hệ sinh thái liên quan <a class="header-anchor" href="#he-sinh-thai-lien-quan" aria-label="Permalink to &quot;Hệ sinh thái liên quan&quot;">​</a></h2><ul><li><a href="/py-xiaozhi/vi/ecosystem/">Hệ sinh thái liên quan</a> - Hệ sinh thái và các dự án mở rộng liên quan đến py-xiaozhi</li></ul><h2 id="thong-tin-phien-ban" tabindex="-1">Thông tin phiên bản <a class="header-anchor" href="#thong-tin-phien-ban" aria-label="Permalink to &quot;Thông tin phiên bản&quot;">​</a></h2><p>Cập nhật tài liệu lần cuối: Tháng 1 năm 2026</p>',18)]))}const m=i(c,[["render",g]]);export{d as __pageData,m as default};
